/**
 * 阿抖 v1.5.8.4 - 指纹降权补丁
 *
 * 作用：把"跨域 CDN URL 的 chrome.downloads.download 调用"转成
 * "fetch → Blob → blob: URL 的本地下载"，降低"高频跨域下载"
 * 被浏览器安全插件识别为"高危下载类插件"的指纹。
 *
 * 启用条件：仅当 chrome.storage.local 中 chromeDownload===true
 * 时走 blob 转换路径；否则保持原 chrome.downloads 行为。
 * 与 js/background.js 内 "downloadUrl" 分支的 chromeDownload 开关
 * 语义一致，用户可在 setting.html 切换。
 *
 * 如果不需要本补丁：把本段删掉、并把 manifest.json 的
 * background.service_worker 改回 "js/background.js" 即可。
 */
(() => {
  "use strict";
  if (chrome.__xsjDownloadOverlay) return;
  chrome.__xsjDownloadOverlay = true;

  const origDownload = chrome.downloads.download.bind(chrome.downloads);

  chrome.downloads.download = async (options) => {
    let useChromeDownloads = false;
    try {
      const stored = await chrome.storage.local.get("chromeDownload");
      useChromeDownloads = Boolean(stored && stored.chromeDownload);
    } catch (e) {
      useChromeDownloads = false;
    }

    if (useChromeDownloads) {
      return origDownload(options);
    }

    const url = options.url;
    if (!/^https?:/i.test(url || "")) {
      return origDownload(options);
    }

    try {
      const resp = await fetch(url, { credentials: "omit" });
      if (!resp.ok) throw new Error("download failed: " + resp.status);
      const blob = await resp.blob();
      const objectUrl = URL.createObjectURL(blob);
      try {
        const id = await origDownload({ ...options, url: objectUrl });
        setTimeout(() => URL.revokeObjectURL(objectUrl), 30000);
        return id;
      } catch (err) {
        URL.revokeObjectURL(objectUrl);
        throw err;
      }
    } catch (err) {
      // fetch 失败（CORS/网络）时回落原 chrome.downloads 跨域下载，
      // 保证下载能力不中断；仅放弃"指纹降权"这一层优化。
      return origDownload(options);
    }
  };
})();

